import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"延时器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/delay/index.md","filePath":"v0.1.0-alpha/modules/delay/index.md"}'),r={name:"v0.1.0-alpha/modules/delay/index.md"};function c(i,t,l,n,h,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="延时器" tabindex="-1">延时器 <a class="header-anchor" href="#延时器" aria-label="Permalink to &quot;延时器&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>delay</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>让输入数据推迟若干 item 后出现在输出中，用于研究时间差、相位差和多路对齐。每对输入／输出独立通过同一个延时量，延时不会改变长期采样率。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p>第一路使用 <code>上游.out → 延时器.in</code>，取 <code>延时器.out</code>；增加端口对后使用 <code>in2 → out2</code> 等对应路径。<code>dly</code> 是消息输入，不能接数值流。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输入</td><td><code>dly</code>（dly（消息））</td><td><code>message</code></td><td>消息；不计入流路数</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>延时按 item 计。标量时，一个 item 是一个数；向量时，一个 item 包含整组分量，延时会一起移动这组数据。延时时间等于延时 item 数除以 item 采样率。</p><p>各端口对采用相容的数据形状；改变向量长度不能当作改变延时单位。起始处的填充区与后续推迟的真实输入要分开观察。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>延时采样数<br><code>delay_samples</code></td><td><code>0</code></td><td>范围 0 至 2147483647</td><td>可在线应用</td></tr><tr><td>输入／输出对数<br><code>num_ports</code></td><td><code>1</code></td><td>范围 1 至 1024；当前画布支持 1–1024 路。修改后须重新准备，缩减前请先解除相关连线和工具绑定。</td><td>重新准备</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr><tr><td>元素类型<br><code>element_type</code></td><td><code>numeric_f64</code></td><td>实数 float32 (<code>numeric_f64</code>)；有符号 int16 (<code>int16</code>)；有符号 int32 (<code>int32</code>)；无符号 byte (<code>byte_u8</code>)</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>delay_samples</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>改变延时量会改变流内部状态，观察切换附近的实际输出，不假定存在已标注的精确样本边界。端口对数、类型或向量长度改变后重新准备。向 <code>dly</code> 发送整数是一次运行时消息，保存工程不会自动重发。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><h3 id="int16-向量-item、双端口延时与流标签" tabindex="-1">int16 向量 item、双端口延时与流标签 <a class="header-anchor" href="#int16-向量-item、双端口延时与流标签" aria-label="Permalink to &quot;int16 向量 item、双端口延时与流标签&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/vector-items-tags.cnsproj" download>下载 vector-items-tags.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>int16 向量 item、双端口延时与流标签</p><ul><li>每个 item 有 4 个 int16 分量；1 item 延时移动整组分量。标签 offset=1 表示第 2 个 item，显式选择第 3 分量观察。</li></ul><h3 id="原生消息输入与实际输出" tabindex="-1">原生消息输入与实际输出 <a class="header-anchor" href="#原生消息输入与实际输出" aria-label="Permalink to &quot;原生消息输入与实际输出&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/message-control.cnsproj" download>下载 message-control.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>原生消息输入与实际输出</p><p>按 F5 运行工程时使用保存的初始参数。运行中可通过消息接口发送下列内容，属性页暂无消息发送入口：</p><table tabindex="0"><thead><tr><th>目标节点</th><th>消息端口</th><th>消息内容</th></tr></thead><tbody><tr><td><code>delay</code></td><td><code>dly</code></td><td><code>2</code></td></tr><tr><td><code>constant</code></td><td><code>cmd</code></td><td><code>{&quot;ampl&quot;: 3, &quot;offset&quot;: 2}</code></td></tr></tbody></table><p>消息作用于后续输出；重新打开工程不会重放上次发送的消息。</p><p>实数处理示例采用 8 item 延时；向量示例采用 1 item 延时，整组四个分量一起移动。</p><p>向运行中的 <code>dly</code> 消息端口发送整数 2，可将后续输出延时改为 2 个 item。属性页暂无消息发送入口；按 F5 运行下载工程时，使用其中保存的初始延时。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>四分量向量延时 1 是移动一个分量吗？</strong> 不是，移动一个完整 item，即一整组四个分量。</p><p><strong>改了参数但时间轴没有整体平移？</strong> 延时器改变输出数据内容；Master 保留输出自身的逻辑时间轴，不替你移动横轴。</p>',41)])])}const u=e(r,[["render",c]]);export{m as __pageData,u as default};
